1	import { readFileSync } from "node:fs";
2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	const STDIN_FILE_DESCRIPTOR = 0;
5	
6	const readScenarioFromStdin = (): Scenario =>
7	  JSON.parse(readFileSync(STDIN_FILE_DESCRIPTOR, "utf8")) as Scenario;
8	
9	const main = (): void => {
10	  try {
11	    process.stdout.write(JSON.stringify(runScenario(readScenarioFromStdin())));
12	  } catch (error) {
13	    process.stderr.write(`${(error as Error).message}\n`);
14	    process.exit(1);
15	  }
16	};
17	
18	main();
