1	import { describe, it, expect } from "vitest";
2	import { spawn } from "node:child_process";
3	import { fileURLToPath } from "node:url";
4	
5	const CLI_PATH = fileURLToPath(new URL("./cli.ts", import.meta.url));
6	
7	type CliRun = {
8	  stdout: string;
9	  stderr: string;
10	  exitCode: number | null;
11	};
12	
13	const runCli = (input: string): Promise<CliRun> =>
14	  new Promise((resolve, reject) => {
15	    const child = spawn("pnpm", ["exec", "tsx", CLI_PATH], {
16	      stdio: ["pipe", "pipe", "pipe"],
17	    });
18	    let stdout = "";
19	    let stderr = "";
20	    child.stdout.on("data", (chunk) => (stdout += String(chunk)));
21	    child.stderr.on("data", (chunk) => (stderr += String(chunk)));
22	    child.on("error", reject);
23	    child.on("close", (exitCode) => resolve({ stdout, stderr, exitCode }));
24	    child.stdin.end(input);
25	  });
26	
27	describe("claim-office CLI", () => {
28	  it("should read a single-step quote scenario from stdin and write the results JSON to stdout with exit code 0", async () => {
29	    const scenario = {
30	      customer: { yearsWithMHPCO: 0 },
31	      steps: [
32	        {
33	          op: "quote",
34	          items: [
35	            {
36	              type: "sword",
37	              material: "steel",
38	              enchantment: 3,
39	              cursed: false,
40	            },
41	          ],
42	        },
43	      ],
44	    };
45	
46	    const { stdout, exitCode } = await runCli(JSON.stringify(scenario));
47	
48	    expect(JSON.parse(stdout)).toEqual({ results: [{ premium: 115 }] });
49	    expect(exitCode).toBe(0);
50	  });
51	  it("should write one result per step, in order, for a multi-step quote-then-claim scenario", async () => {
52	    const scenario = {
53	      customer: { yearsWithMHPCO: 5 },
54	      steps: [
55	        {
56	          op: "quote",
57	          items: [
58	            {
59	              type: "amulet",
60	              material: "silver",
61	              enchantment: 2,
62	              cursed: false,
63	            },
64	          ],
65	        },
66	        {
67	          op: "claim",
68	          policy: 0,
69	          incident: {
70	            cause: "fire",
71	            damages: [{ itemType: "amulet", amount: 200 }],
72	          },
73	        },
74	      ],
75	    };
76	
77	    const { stdout, exitCode } = await runCli(JSON.stringify(scenario));
78	
79	    expect(JSON.parse(stdout)).toEqual({
80	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
81	    });
82	    expect(exitCode).toBe(0);
83	  });
84	  it("should exit with a non-zero status code and write an error description to stderr when the scenario is rejected", async () => {
85	    const scenario = {
86	      customer: { yearsWithMHPCO: 0 },
87	      steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
88	    };
89	
90	    const { stderr, exitCode } = await runCli(JSON.stringify(scenario));
91	
92	    expect(exitCode).not.toBe(0);
93	    expect(stderr.trim()).not.toBe("");
94	    expect(stderr).toContain("broomstick");
95	    expect(stderr).not.toMatch(/^\s*at /m);
96	    expect(stderr).not.toContain("throw ");
97	  });
98	  it.todo("should write nothing to stdout when the scenario is rejected");
99	});
